    private void shell(String command)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command))){while(in.read()!=-1){}}}
    private void rotate(int orientation)throws Exception{ui(()->home.setRequestedOrientation(orientation));SystemClock.sleep(700);waitForIdleSync();}
    private void ui(Runnable action)throws Exception{FutureTask<Void> task=new FutureTask<>(action,null);home.runOnUiThread(task);task.get(20,TimeUnit.SECONDS);waitForIdleSync();}
    private void shot(String name)throws Exception{waitForIdleSync();SystemClock.sleep(200);Bitmap image=getUiAutomation().takeScreenshot();if(image==null||blank(image)){if(image!=null)image.recycle();image=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);Bitmap capture=image;ui(()->root.draw(new Canvas(capture)));}try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}}
    private static boolean blank(Bitmap image){for(int y=0;y<image.getHeight();y+=20)for(int x=0;x<image.getWidth();x+=20)if((image.getPixel(x,y)&0xffffff)!=0)return false;return true;}
    private View popup(BrowserPanel browser){try{java.lang.reflect.Field field=BrowserPanel.class.getDeclaredField("pinPopup");field.setAccessible(true);return ((PopupWindow)field.get(browser)).getContentView();}catch(Exception e){throw new RuntimeException(e);}}
